import{_ as i,o as a,c as e,aN as r}from"./chunks/framework.D31DlcCL.js";const t="/img/edu-guiyi.svg",u="/img/edu-guizong.svg",p=JSON.parse('{"title":"小学数学应用题技巧讲解①：归一问题与归总问题","description":"系统讲解归一与归总两类常见应用题，结合图解法、分析法与参考法，配详细示例与易错点。","frontmatter":{"title":"小学数学应用题技巧讲解①：归一问题与归总问题","date":"2026-01-14T12:00:00.000Z","categories":["数学"],"tags":["小学数学","应用题","归一问题","归总问题","图解法","分析法","参考法"],"description":"系统讲解归一与归总两类常见应用题，结合图解法、分析法与参考法，配详细示例与易错点。","cover":"/img/banner.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/xiaoxue-shuxue-guiyi-guizong.md","filePath":"posts/xiaoxue-shuxue-guiyi-guizong.md","lastUpdated":null}'),o={name:"posts/xiaoxue-shuxue-guiyi-guizong.md"};function h(n,l,s,d,c,_){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="小学数学应用题技巧讲解1-归一问题与归总问题" tabindex="-1">小学数学应用题技巧讲解①：归一问题与归总问题 <a class="header-anchor" href="#小学数学应用题技巧讲解1-归一问题与归总问题" aria-label="Permalink to &quot;小学数学应用题技巧讲解①：归一问题与归总问题&quot;">​</a></h1><p>本文围绕两类高频应用题：归一问题与归总问题。通过“图解法 + 分析法 + 参考法”的组合，帮助学生建立稳定的解题框架，提升正确率与速度。</p><h2 id="一、核心概念速览" tabindex="-1">一、核心概念速览 <a class="header-anchor" href="#一、核心概念速览" aria-label="Permalink to &quot;一、核心概念速览&quot;">​</a></h2><ul><li>归一问题：先把数量“归到 1 单位”，再扩展到 N 单位。关键是单位量。</li><li>归总问题：先把各部分“归到总量”，再根据总量反推平均或单位量。关键是分组求和。</li></ul><p>配图示意：</p><ul><li>归一问题：<img src="'+t+'" alt="归一问题示意"></li><li>归总问题：<img src="'+u+'" alt="归总问题示意"></li></ul><h2 id="二、归一问题" tabindex="-1">二、归一问题 <a class="header-anchor" href="#二、归一问题" aria-label="Permalink to &quot;二、归一问题&quot;">​</a></h2><h3 id="_1-思路框架-分析法" tabindex="-1">1. 思路框架（分析法） <a class="header-anchor" href="#_1-思路框架-分析法" aria-label="Permalink to &quot;1. 思路框架（分析法）&quot;">​</a></h3><ol><li>找“单位”：人/份/小时/米等</li><li>求“1 单位量”：总量 ÷ 单位数量</li><li>扩展到 N 单位：单位量 × N</li><li>检查维度与条件：单位、时间、数量是否一致</li></ol><h3 id="_2-图解法" tabindex="-1">2. 图解法 <a class="header-anchor" href="#_2-图解法" aria-label="Permalink to &quot;2. 图解法&quot;">​</a></h3><ul><li>把题目转成“单位量”与“总量”的关系图；先定位“1 单位”，再连线到结果。</li></ul><h3 id="_3-示例讲解" tabindex="-1">3. 示例讲解 <a class="header-anchor" href="#_3-示例讲解" aria-label="Permalink to &quot;3. 示例讲解&quot;">​</a></h3><p>例 1（蛋糕分配）<br> “8 个蛋糕平均分给 4 个孩子，每个孩子分到几个？”</p><ul><li>单位：孩子</li><li>1 单位量：8 ÷ 4 = 2（每个孩子 2 个）</li><li>答：2 个</li></ul><p>例 2（工作效率）<br> “甲乙两人 3 小时共加工 12 件，平均每人每小时加工几件？”</p><ul><li>总人数 × 总时间 = 人时数：2 × 3 = 6 人·小时</li><li>单位量（每人每小时）：12 ÷ 6 = 2 件/人·小时</li><li>答：2 件/人·小时</li></ul><p>例 3（速度问题）<br> “一辆小车 2 小时行驶 120 千米，平均每小时行驶多少千米？”</p><ul><li>单位量（每小时）：120 ÷ 2 = 60 千米/小时</li><li>答：60 千米/小时</li></ul><h3 id="_4-易错点与参考法" tabindex="-1">4. 易错点与参考法 <a class="header-anchor" href="#_4-易错点与参考法" aria-label="Permalink to &quot;4. 易错点与参考法&quot;">​</a></h3><ul><li>易错 1：忘记“人时数”，把 12 ÷ 3 = 4（错） <ul><li>参考法：遇到“多人多小时”，先把“人数×时间”合并为人时量。</li></ul></li><li>易错 2：单位混淆，如把“每人每小时”写成“每人每两小时” <ul><li>参考法：写单位时“人/小时/件”三个维度要齐全。</li></ul></li></ul><h2 id="三、归总问题" tabindex="-1">三、归总问题 <a class="header-anchor" href="#三、归总问题" aria-label="Permalink to &quot;三、归总问题&quot;">​</a></h2><h3 id="_1-思路框架-分析法-1" tabindex="-1">1. 思路框架（分析法） <a class="header-anchor" href="#_1-思路框架-分析法-1" aria-label="Permalink to &quot;1. 思路框架（分析法）&quot;">​</a></h3><ol><li>列出各部分数量（可分组）</li><li>求总量：把各部分相加</li><li>反推：平均/单位量/剩余</li><li>检查是否有重叠或遗漏</li></ol><h3 id="_2-图解法-1" tabindex="-1">2. 图解法 <a class="header-anchor" href="#_2-图解法-1" aria-label="Permalink to &quot;2. 图解法&quot;">​</a></h3><ul><li>将 A、B、C… 各组用方块表示，右侧汇总为“总计”，再从总计反推平均或单位量。</li></ul><h3 id="_3-示例讲解-1" tabindex="-1">3. 示例讲解 <a class="header-anchor" href="#_3-示例讲解-1" aria-label="Permalink to &quot;3. 示例讲解&quot;">​</a></h3><p>例 1（班级水果）<br> “三组同学分别带来 6、8、10 个苹果，一共多少个？平均每组多少个？”</p><ul><li>总量：6 + 8 + 10 = 24</li><li>平均每组：24 ÷ 3 = 8</li><li>答：总计 24 个，平均每组 8 个</li></ul><p>例 2（书本统计）<br> “一班语文书 15 本、数学书 18 本、英语书 17 本，总数？每个学科平均多少？”</p><ul><li>总量：15 + 18 + 17 = 50</li><li>平均每科：50 ÷ 3 ≈ 16.7（保留 16 或 17，视题目要求）</li><li>答：50 本；平均约 17 本/科</li></ul><p>例 3（工队用水）<br> “甲 4 桶，乙 5 桶，丙 3 桶，共用多少？若平均每队用多少？”</p><ul><li>总量：4 + 5 + 3 = 12 桶</li><li>平均每队：12 ÷ 3 = 4 桶/队</li><li>答：12 桶；平均 4 桶/队</li></ul><h3 id="_4-易错点与参考法-1" tabindex="-1">4. 易错点与参考法 <a class="header-anchor" href="#_4-易错点与参考法-1" aria-label="Permalink to &quot;4. 易错点与参考法&quot;">​</a></h3><ul><li>易错 1：漏加某一组或重复计算 <ul><li>参考法：先列清单 A、B、C…，打勾确认再求和。</li></ul></li><li>易错 2：平均时除以错误的组数 <ul><li>参考法：明确“平均对象”是组、人还是天，对应分母不同。</li></ul></li></ul><h2 id="四、归一-vs-归总-如何选择" tabindex="-1">四、归一 vs 归总：如何选择 <a class="header-anchor" href="#四、归一-vs-归总-如何选择" aria-label="Permalink to &quot;四、归一 vs 归总：如何选择&quot;">​</a></h2><ul><li>看问法： <ul><li>问“每人/每小时/每份” → 往往归一</li><li>问“总共/一共/合计” → 往往归总</li></ul></li><li>看条件： <ul><li>给了总量和单位数量 → 归一</li><li>给了分组明细 → 归总</li></ul></li><li>综合题：先归总再归一，或先归一再归总（如先求单位量，后算全班总量）</li></ul><h2 id="五、进阶练习-结合两法" tabindex="-1">五、进阶练习（结合两法） <a class="header-anchor" href="#五、进阶练习-结合两法" aria-label="Permalink to &quot;五、进阶练习（结合两法）&quot;">​</a></h2><p>练 1<br> “4 个同学用 2 小时做了 16 朵花，平均每人每小时做几朵？如果再做 3 小时，共能做多少朵？”</p><ul><li>步骤 1（归一）：人时数=4×2=8；单位量=16÷8=2 朵/人·小时</li><li>步骤 2（扩展）：再做 3 小时的人时数=4×3=12；增加量=2×12=24 朵</li><li>总量：16 + 24 = 40 朵</li></ul><p>练 2<br> “甲乙丙三组各做 5、7、6 本手工册，平均每组多少？若每组再做 2 本，总数？”</p><ul><li>归总：5+7+6=18；平均=18÷3=6</li><li>扩展：每组再做 2，本组总增=2×3=6；新总=18+6=24</li></ul><h2 id="六、课堂建议" tabindex="-1">六、课堂建议 <a class="header-anchor" href="#六、课堂建议" aria-label="Permalink to &quot;六、课堂建议&quot;">​</a></h2><ul><li>解题四步：读题→画图→列量→核对单位</li><li>训练重点：单位量与人时量、分组清单与平均分母</li><li>错题本：记录“单位错”“分母错”“漏加错”，下次先查清单再计算</li></ul><hr><p>欢迎在评论区反馈常见错题，我会在后续篇章补充“和差倍比”“行程与工程”“浓度与比例”等专题讲解。</p>',45)])])}const m=i(o,[["render",h]]);export{p as __pageData,m as default};
